-- Blue Flame tenant-aware core schema. Apply with `supabase db push`.
create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','counter_staff','delivery_worker','storekeeper','auditor','customer');
create type public.booking_status as enum ('pending','assigned','dispatched','delivered','cancelled','requires_review');
create type public.case_status as enum ('open','under_review','awaiting_evidence','resolved','dismissed');

create table public.distributorships(
 id uuid primary key default gen_random_uuid(), name text not null, currency_code text not null default 'INR', created_at timestamptz not null default now()
);
create table public.profiles(
 id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', preferred_language text not null default 'en' check(preferred_language in ('en','hi','te','ta','kn','ml','mr','bn')), created_at timestamptz not null default now()
);
create table public.memberships(
 tenant_id uuid not null references public.distributorships(id), user_id uuid not null references public.profiles(id), role public.member_role not null, active boolean not null default true, village_id uuid, created_at timestamptz not null default now(), primary key(tenant_id,user_id)
);
create table public.villages(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.distributorships(id), name text not null, unique(tenant_id,name), unique(tenant_id,id));
alter table public.memberships add constraint memberships_village_tenant_fk foreign key(tenant_id,village_id) references public.villages(tenant_id,id);
create table public.customers(
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.distributorships(id), village_id uuid not null, customer_no text not null, auth_user_id uuid references auth.users(id), full_name text not null, mobile text not null, address text not null default '', active boolean not null default true, registered_at date not null default current_date, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,customer_no), unique(tenant_id,id), foreign key(tenant_id,village_id) references public.villages(tenant_id,id)
);
create index customers_tenant_name_idx on public.customers(tenant_id,full_name);
create index customers_tenant_mobile_idx on public.customers(tenant_id,mobile);
create table public.bookings(
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.distributorships(id), customer_id uuid not null, booking_ref text not null, status public.booking_status not null default 'pending', booked_at timestamptz not null default now(), expected_amount numeric(12,2) not null check(expected_amount>0), assigned_worker uuid references public.profiles(id), idempotency_key uuid not null, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), unique(tenant_id,booking_ref), unique(tenant_id,idempotency_key), unique(tenant_id,id), foreign key(tenant_id,customer_id) references public.customers(tenant_id,id)
);
create index bookings_tenant_status_date_idx on public.bookings(tenant_id,status,booked_at desc);
create index bookings_tenant_customer_idx on public.bookings(tenant_id,customer_id,booked_at desc);
create table public.deliveries(
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.distributorships(id), booking_id uuid not null, worker_id uuid not null references public.profiles(id), delivered_at timestamptz not null, full_cylinders_out integer not null default 1 check(full_cylinders_out>=0), empty_cylinders_in integer not null default 0 check(empty_cylinders_in>=0), remarks text not null default '', offline_client_id uuid not null, created_at timestamptz not null default now(), unique(tenant_id,offline_client_id), unique(tenant_id,booking_id), foreign key(tenant_id,booking_id) references public.bookings(tenant_id,id)
);
create table public.payments(
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.distributorships(id), customer_id uuid not null, booking_id uuid, amount numeric(12,2) not null check(amount>0), method text not null check(method in ('cash','upi','bank_transfer','other')), reference text, verification_status text not null default 'recorded' check(verification_status in ('recorded','simulated_unverified','bank_verified','reversed')), collected_by uuid not null references public.profiles(id), collected_at timestamptz not null default now(), idempotency_key uuid not null, correction_of uuid references public.payments(id), correction_reason text, unique(tenant_id,idempotency_key), unique(tenant_id,id), foreign key(tenant_id,customer_id) references public.customers(tenant_id,id), foreign key(tenant_id,booking_id) references public.bookings(tenant_id,id), check((correction_of is null and correction_reason is null) or (correction_of is not null and length(trim(correction_reason))>0))
);
create index payments_tenant_date_idx on public.payments(tenant_id,collected_at desc);
create index payments_tenant_booking_idx on public.payments(tenant_id,booking_id);
create table public.settlement_records(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.distributorships(id),source text not null,source_ref text not null,amount numeric(12,2) not null,settled_at timestamptz not null,imported_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(tenant_id,source,source_ref));
create table public.cylinder_locations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.distributorships(id),name text not null,location_type text not null check(location_type in ('depot','store','worker','supplier','inspection')),owner_user_id uuid references public.profiles(id),unique(tenant_id,name),unique(tenant_id,id));
create table public.cylinder_movements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.distributorships(id),cylinder_state text not null check(cylinder_state in ('full','empty','defective')),source_location uuid not null,destination_location uuid not null,quantity integer not null check(quantity>0),reason text not null,related_booking uuid,responsible_user uuid not null references public.profiles(id),occurred_at timestamptz not null default now(),idempotency_key uuid not null,confirmed_at timestamptz,correction_of uuid references public.cylinder_movements(id),correction_reason text,unique(tenant_id,idempotency_key),foreign key(tenant_id,source_location) references public.cylinder_locations(tenant_id,id),foreign key(tenant_id,destination_location) references public.cylinder_locations(tenant_id,id),foreign key(tenant_id,related_booking) references public.bookings(tenant_id,id),check(source_location<>destination_location),check((correction_of is null and correction_reason is null) or (correction_of is not null and length(trim(correction_reason))>0)));
create index movements_tenant_time_idx on public.cylinder_movements(tenant_id,occurred_at desc);
create table public.inventory_counts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.distributorships(id),location_id uuid not null,full_count integer not null check(full_count>=0),empty_count integer not null check(empty_count>=0),defective_count integer not null check(defective_count>=0),counted_by uuid not null references public.profiles(id),counted_at timestamptz not null default now(),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,notes text not null default '',foreign key(tenant_id,location_id) references public.cylinder_locations(tenant_id,id));
create table public.subsidy_records(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.distributorships(id),customer_id uuid not null,booking_id uuid,eligibility_status text not null check(eligibility_status in ('not_verified','pending_processing','recorded','confirmed_authorized_source','requires_investigation')),expected_amount numeric(12,2),recorded_amount numeric(12,2),source text,source_reference text,verification_status text not null default 'not_verified',reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,created_at timestamptz not null default now(),foreign key(tenant_id,customer_id) references public.customers(tenant_id,id),foreign key(tenant_id,booking_id) references public.bookings(tenant_id,id));
create table public.disputes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.distributorships(id),customer_id uuid not null,booking_id uuid,category text not null,description text not null,evidence jsonb not null default '[]',status public.case_status not null default 'open',assigned_to uuid references public.profiles(id),resolution text,created_at timestamptz not null default now(),resolved_at timestamptz,foreign key(tenant_id,customer_id) references public.customers(tenant_id,id),foreign key(tenant_id,booking_id) references public.bookings(tenant_id,id));
create table public.discrepancy_cases(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.distributorships(id),category text not null,severity text not null check(severity in ('low','medium','high','critical')),linked_records jsonb not null default '[]',expected_value jsonb,actual_value jsonb,explanation text not null,status public.case_status not null default 'open',reviewer uuid references public.profiles(id),resolution_notes text,created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.audit_logs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.distributorships(id),actor uuid references public.profiles(id),action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
create index audit_tenant_created_idx on public.audit_logs(tenant_id,created_at desc);
create table public.offline_sync_records(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.distributorships(id),client_id uuid not null,user_id uuid not null references public.profiles(id),entity_type text not null,payload jsonb not null,status text not null default 'queued' check(status in ('queued','acknowledged','conflict')),received_at timestamptz not null default now(),acknowledged_at timestamptz,conflict_reason text,unique(tenant_id,client_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.distributorships(id),user_id uuid not null references public.profiles(id),title text not null,body text not null,language text not null default 'en',read_at timestamptz,created_at timestamptz not null default now());

alter table public.profiles enable row level security;
create policy profile_self_read on public.profiles for select to authenticated using(id=auth.uid());
create policy profile_self_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create or replace function public.has_tenant_role(p_tenant uuid,p_roles public.member_role[] default null) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from memberships m where m.tenant_id=p_tenant and m.user_id=auth.uid() and m.active and (p_roles is null or m.role=any(p_roles))) $$;
revoke all on function public.has_tenant_role(uuid,public.member_role[]) from public;
grant execute on function public.has_tenant_role(uuid,public.member_role[]) to authenticated;
do $$ declare t text; begin foreach t in array array['distributorships','memberships','villages','customers','bookings','deliveries','payments','settlement_records','cylinder_locations','cylinder_movements','inventory_counts','subsidy_records','disputes','discrepancy_cases','audit_logs','offline_sync_records','notifications'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy tenant_read_distributorships on public.distributorships for select to authenticated using(public.has_tenant_role(id));
create policy memberships_read on public.memberships for select to authenticated using(public.has_tenant_role(tenant_id));
create policy memberships_owner_manage on public.memberships for all to authenticated using(public.has_tenant_role(tenant_id,array['owner']::public.member_role[])) with check(public.has_tenant_role(tenant_id,array['owner']::public.member_role[]));
create policy villages_access on public.villages for all to authenticated using(public.has_tenant_role(tenant_id)) with check(public.has_tenant_role(tenant_id,array['owner','counter_staff','storekeeper']::public.member_role[]));
create policy customers_access on public.customers for all to authenticated using(public.has_tenant_role(tenant_id) and (auth_user_id is null or auth_user_id=auth.uid() or public.has_tenant_role(tenant_id,array['owner','counter_staff']::public.member_role[]))) with check(public.has_tenant_role(tenant_id,array['owner','counter_staff']::public.member_role[]));
create policy bookings_read on public.bookings for select to authenticated using(public.has_tenant_role(tenant_id) and (public.has_tenant_role(tenant_id,array['owner','counter_staff','auditor']::public.member_role[]) or assigned_worker=auth.uid() or exists(select 1 from customers c where c.id=customer_id and c.auth_user_id=auth.uid())));
create policy bookings_create on public.bookings for insert to authenticated with check(public.has_tenant_role(tenant_id,array['owner','counter_staff']::public.member_role[]) and created_by=auth.uid());
create policy bookings_update on public.bookings for update to authenticated using(public.has_tenant_role(tenant_id,array['owner','counter_staff']::public.member_role[])) with check(public.has_tenant_role(tenant_id,array['owner','counter_staff']::public.member_role[]));
create policy delivery_access on public.deliveries for select to authenticated using(public.has_tenant_role(tenant_id) and (public.has_tenant_role(tenant_id,array['owner','counter_staff','auditor']::public.member_role[]) or worker_id=auth.uid()));
create policy delivery_create on public.deliveries for insert to authenticated with check(public.has_tenant_role(tenant_id,array['owner','delivery_worker']::public.member_role[]) and worker_id=auth.uid());
create policy payments_read on public.payments for select to authenticated using(public.has_tenant_role(tenant_id) and (public.has_tenant_role(tenant_id,array['owner','counter_staff','auditor']::public.member_role[]) or exists(select 1 from customers c where c.id=customer_id and c.auth_user_id=auth.uid())));
create policy payments_insert on public.payments for insert to authenticated with check(public.has_tenant_role(tenant_id,array['owner','counter_staff']::public.member_role[]) and collected_by=auth.uid());
create policy settlements_owner_audit_read on public.settlement_records for select to authenticated using(public.has_tenant_role(tenant_id,array['owner','auditor']::public.member_role[]));
create policy cylinder_locations_access on public.cylinder_locations for all to authenticated using(public.has_tenant_role(tenant_id)) with check(public.has_tenant_role(tenant_id,array['owner','storekeeper']::public.member_role[]));
create policy movements_access on public.cylinder_movements for select to authenticated using(public.has_tenant_role(tenant_id));
create policy movement_insert on public.cylinder_movements for insert to authenticated with check(public.has_tenant_role(tenant_id,array['owner','storekeeper','delivery_worker']::public.member_role[]) and responsible_user=auth.uid());
create policy counts_access on public.inventory_counts for all to authenticated using(public.has_tenant_role(tenant_id)) with check(public.has_tenant_role(tenant_id,array['owner','storekeeper']::public.member_role[]) and counted_by=auth.uid());
create policy subsidies_access on public.subsidy_records for all to authenticated using(public.has_tenant_role(tenant_id) and (public.has_tenant_role(tenant_id,array['owner','counter_staff','auditor']::public.member_role[]) or exists(select 1 from customers c where c.id=customer_id and c.auth_user_id=auth.uid()))) with check(public.has_tenant_role(tenant_id,array['owner','counter_staff']::public.member_role[]));
create policy disputes_access on public.disputes for all to authenticated using(public.has_tenant_role(tenant_id) and (public.has_tenant_role(tenant_id,array['owner','counter_staff','auditor']::public.member_role[]) or exists(select 1 from customers c where c.id=customer_id and c.auth_user_id=auth.uid()))) with check(public.has_tenant_role(tenant_id,array['owner','counter_staff']::public.member_role[]) or (public.has_tenant_role(tenant_id,array['customer']::public.member_role[]) and exists(select 1 from customers c where c.id=customer_id and c.auth_user_id=auth.uid())));
create policy discrepancies_read on public.discrepancy_cases for select to authenticated using(public.has_tenant_role(tenant_id));
create policy discrepancies_resolve on public.discrepancy_cases for update to authenticated using(public.has_tenant_role(tenant_id,array['owner','auditor']::public.member_role[])) with check(public.has_tenant_role(tenant_id,array['owner','auditor']::public.member_role[]));
create policy audit_read on public.audit_logs for select to authenticated using(public.has_tenant_role(tenant_id,array['owner','auditor']::public.member_role[]));
create policy audit_append on public.audit_logs for insert to authenticated with check(public.has_tenant_role(tenant_id) and actor=auth.uid());
create policy sync_access on public.offline_sync_records for all to authenticated using(public.has_tenant_role(tenant_id) and (user_id=auth.uid() or public.has_tenant_role(tenant_id,array['owner']::public.member_role[]))) with check(public.has_tenant_role(tenant_id) and user_id=auth.uid());
create policy notifications_access on public.notifications for all to authenticated using(public.has_tenant_role(tenant_id) and user_id=auth.uid()) with check(public.has_tenant_role(tenant_id) and user_id=auth.uid());
-- Append-only logs: no UPDATE or DELETE policies are defined. Corrections use linked reversal records.
